DROP TABLE IF EXISTS `assets_asset`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `assets_asset` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `asset_code` varchar(100) DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `renewal_date` date DEFAULT NULL,
  `renewal_cycle_days` int(10) unsigned DEFAULT NULL CHECK (`renewal_cycle_days` >= 0),
  `renewal_reminder_days` int(10) unsigned DEFAULT NULL CHECK (`renewal_reminder_days` >= 0),
  `serial_number` varchar(255) DEFAULT NULL,
  `tag_number` varchar(100) DEFAULT NULL,
  `purchase_date` date DEFAULT NULL,
  `purchase_cost` decimal(12,2) DEFAULT NULL,
  `purchase_narration` longtext DEFAULT NULL,
  `warranty_start_date` date DEFAULT NULL,
  `warranty_end_date` date DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `status` varchar(20) DEFAULT NULL,
  `condition` varchar(20) DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `depreciation_percentage` decimal(5,2) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `category_id` bigint(20) DEFAULT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `department_id` bigint(20) DEFAULT NULL,
  `incharge_id` bigint(20) DEFAULT NULL,
  `sss` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `asset_code` (`asset_code`),
  KEY `assets_asset_category_id_b30c6baf_fk_assets_assetcategory_id` (`category_id`),
  KEY `assets_asset_created_by_id_4d70f031_fk_register_` (`created_by_id`),
  KEY `assets_asset_department_id_027e8197_fk_rarenett_` (`department_id`),
  KEY `assets_asset_incharge_id_8b9c4c46_fk_register_app_customuser_id` (`incharge_id`),
