  `positive_feedback` longtext DEFAULT NULL,
  `negative_feedback` longtext DEFAULT NULL,
  `decision_type` varchar(20) DEFAULT NULL,
  `responder_remarks` longtext DEFAULT NULL,
  `responder_attachment` varchar(100) DEFAULT NULL,
  `admin_decision` varchar(20) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `assigned_to_id` bigint(20) DEFAULT NULL,
  `category_id` bigint(20) DEFAULT NULL,
  `pattern_id` bigint(20) DEFAULT NULL,
  `user_id` bigint(20) DEFAULT NULL,
  `cutoff_date` date DEFAULT NULL,
  `admin_remarks` longtext DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `complaint_app_compla_assigned_to_id_01da9cbf_fk_register_` (`assigned_to_id`),
