  CONSTRAINT `complaint_app_compla_category_id_544f2011_fk_complaint` FOREIGN KEY (`category_id`) REFERENCES `complaint_app_complaintcategory` (`id`),
  CONSTRAINT `complaint_app_compla_pattern_id_5e76e058_fk_complaint` FOREIGN KEY (`pattern_id`) REFERENCES `complaint_app_pattern` (`id`),
  CONSTRAINT `complaint_app_compla_user_id_1e710007_fk_register_` FOREIGN KEY (`user_id`) REFERENCES `register_app_customuser` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=33 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
