DROP TABLE IF EXISTS `crm_leadimportstaging`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `crm_leadimportstaging` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `row_number` int(11) NOT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `first_name` varchar(255) DEFAULT NULL,
  `last_name` varchar(255) DEFAULT NULL,
  `company` varchar(255) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `mobile` varchar(255) DEFAULT NULL,
  `title` varchar(255) DEFAULT NULL,
  `category_name` varchar(255) DEFAULT NULL,
  `source_name` varchar(255) DEFAULT NULL,
  `industry_name` varchar(255) DEFAULT NULL,
  `lead_status` varchar(255) DEFAULT NULL,
  `rating` varchar(255) DEFAULT NULL,
  `priority` varchar(255) DEFAULT NULL,
  `estimated_value` varchar(255) DEFAULT NULL,
  `no_of_employees` varchar(255) DEFAULT NULL,
  `annual_revenue` varchar(255) DEFAULT NULL,
  `website` varchar(255) DEFAULT NULL,
  `country` varchar(255) DEFAULT NULL,
  `state_province` varchar(255) DEFAULT NULL,
  `city` varchar(255) DEFAULT NULL,
  `street_address` varchar(255) DEFAULT NULL,
  `zip_postal_code` varchar(255) DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `normalized_phone` varchar(50) DEFAULT NULL,
  `validation_status` varchar(50) NOT NULL,
  `error_messages` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`error_messages`)),
  `is_duplicate_in_file` tinyint(1) NOT NULL,
  `batch_id` bigint(20) NOT NULL,
  `category_id` bigint(20) DEFAULT NULL,
  `existing_lead_id` bigint(20) DEFAULT NULL,
  `industry_id` bigint(20) DEFAULT NULL,
  `lead_source_id` bigint(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `crm_leadimportstaging_batch_id_row_number_4e0a2dfa_uniq` (`batch_id`,`row_number`),
  KEY `crm_leadimportstagin_category_id_49859f88_fk_crm_leadc` (`category_id`),
  KEY `crm_leadimportstaging_existing_lead_id_c219fba0_fk_crm_lead_id` (`existing_lead_id`),
  KEY `crm_leadimportstaging_industry_id_ed887d95_fk_crm_industry_id` (`industry_id`),
  KEY `crm_leadimportstagin_lead_source_id_f2eb4033_fk_crm_leads` (`lead_source_id`),
  KEY `crm_leadimportstaging_normalized_phone_42c0bc3a` (`normalized_phone`),
  CONSTRAINT `crm_leadimportstagin_batch_id_bbd8e16c_fk_crm_leadi` FOREIGN KEY (`batch_id`) REFERENCES `crm_leadimportbatch` (`id`),
  CONSTRAINT `crm_leadimportstagin_category_id_49859f88_fk_crm_leadc` FOREIGN KEY (`category_id`) REFERENCES `crm_leadcategory` (`id`),
  CONSTRAINT `crm_leadimportstagin_lead_source_id_f2eb4033_fk_crm_leads` FOREIGN KEY (`lead_source_id`) REFERENCES `crm_leadsource` (`id`),
  CONSTRAINT `crm_leadimportstaging_existing_lead_id_c219fba0_fk_crm_lead_id` FOREIGN KEY (`existing_lead_id`) REFERENCES `crm_lead` (`id`),
  CONSTRAINT `crm_leadimportstaging_industry_id_ed887d95_fk_crm_industry_id` FOREIGN KEY (`industry_id`) REFERENCES `crm_industry` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=108 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
