DROP TABLE IF EXISTS `wallet_screenshot_schedule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wallet_screenshot_schedule` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) NOT NULL,
  `scheduled_date` date NOT NULL,
  `scheduled_time` time(6) NOT NULL,
  `is_active` tinyint(1) NOT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_active_user_date_time_schedule` (`user_id`,`scheduled_date`,`scheduled_time`),
  KEY `wallet_screenshot_sc_created_by_id_9bd34b54_fk_register_` (`created_by_id`),
  KEY `wallet_screenshot_schedule_scheduled_date_7b6f30b2` (`scheduled_date`),
  KEY `wallet_screenshot_schedule_scheduled_time_752ebfc5` (`scheduled_time`),
  KEY `wallet_screenshot_schedule_is_active_fedf32a6` (`is_active`),
  CONSTRAINT `wallet_screenshot_sc_created_by_id_9bd34b54_fk_register_` FOREIGN KEY (`created_by_id`) REFERENCES `register_app_customuser` (`id`),
  CONSTRAINT `wallet_screenshot_sc_user_id_e8fe1ad2_fk_register_` FOREIGN KEY (`user_id`) REFERENCES `register_app_customuser` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2685 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
