DROP TABLE IF EXISTS `wallet_transaction`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wallet_transaction` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `transaction_number` varchar(50) NOT NULL,
  `transaction_date` date NOT NULL,
  `wallet_id` bigint(20) NOT NULL,
  `transaction_type` varchar(10) NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `reference_number` varchar(100) DEFAULT NULL,
  `description` longtext DEFAULT NULL,
  `status` varchar(20) NOT NULL,
  `cancellation_reason` longtext DEFAULT NULL,
  `created_by_id` bigint(20) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `transaction_number` (`transaction_number`),
  KEY `wallet_transaction_wallet_id_a0ff1b17_fk_wallet_master_id` (`wallet_id`),
  KEY `wallet_transaction_created_by_id_1f9f0253_fk_register_` (`created_by_id`),
  KEY `wallet_transaction_transaction_date_7c1bcb8c` (`transaction_date`),
  KEY `wallet_transaction_transaction_type_ae248167` (`transaction_type`),
  KEY `wallet_transaction_reference_number_fdd1b987` (`reference_number`),
  KEY `wallet_transaction_status_a914a29c` (`status`),
  CONSTRAINT `wallet_transaction_created_by_id_1f9f0253_fk_register_` FOREIGN KEY (`created_by_id`) REFERENCES `register_app_customuser` (`id`),
  CONSTRAINT `wallet_transaction_wallet_id_a0ff1b17_fk_wallet_master_id` FOREIGN KEY (`wallet_id`) REFERENCES `wallet_master` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
